"""Parent integration: actual authenticated routes, SQLite and generated bytes."""

import hashlib
from uuid import uuid4

from fastapi.testclient import TestClient

from desk.app import create_app


def test_owner_source_to_run_to_verified_download_and_logout(tmp_path, monkeypatch):
    monkeypatch.delenv("DESK_BROWSER_ENABLED", raising=False)
    app = create_app(tmp_path, password="fixture-only", scheduler=False)
    with TestClient(app) as client:
        for route in (
            "/api/agent-runs/scope",
            "/api/sources",
            "/api/artifacts",
            "/api/browser/jobs",
        ):
            assert client.get(route).status_code in (401, 403)
        client.headers["X-Desk-Request"] = "1"
        assert (
            client.post(
                "/api/session",
                json={
                    "username": "owner",
                    "password": "fixture-only",
                },
            ).status_code
            == 200
        )
        client.headers["X-Operation-Id"] = uuid4().hex
        upload = client.post(
            "/api/sources/upload?name=requirements.csv&format=csv",
            content=b"item,hours\nread,2\nwrite,3\n",
        )
        assert upload.status_code == 200, upload.text
        source = upload.json()["source"]
        scope = client.get("/api/agent-runs/scope").json()
        assert any(item["id"] == source["id"] for item in scope["sources"])
        client.headers["X-Operation-Id"] = uuid4().hex
        created = client.post(
            "/api/agent-runs",
            json={
                "goal": "Compile these selected requirements.",
                "retain": True,
                "mode": "deterministic",
                "source_ids": [source["id"]],
                "scope_revision": scope["scope_revision"],
            },
        )
        assert created.status_code == 200, created.text
        run_id = created.json()["run"]["id"]
        for _ in range(20):
            app.state.runtime.agent_runs.advance_one()
            result = client.get(f"/api/agent-runs/{run_id}").json()
            if result["run"]["state"] in {"succeeded", "failed", "partial", "blocked"}:
                break
        assert result["run"]["state"] == "succeeded", result
        artifacts = client.get("/api/artifacts", params={"run_id": run_id}).json()["artifacts"]
        assert {item["format"] for item in artifacts} == {"markdown", "csv"}
        for item in artifacts:
            response = client.get(f"/api/artifacts/{item['id']}/download")
            assert response.status_code == 200
            assert hashlib.sha256(response.content).hexdigest() == item["sha256"]
            assert "attachment" in response.headers["Content-Disposition"]
        assert client.get("/api/browser/capabilities").json()["reason"] == "BROWSER_DISABLED"
        assert client.delete("/api/session").status_code == 200
        assert client.get(f"/api/agent-runs/{run_id}").status_code in (401, 403)
        assert client.get(f"/api/artifacts/{artifacts[0]['id']}/download").status_code in (401, 403)
    assert app.state.runtime.agent_runs.stopped
    assert app.state.runtime.browser_jobs.stopping
